    internal static int FtLine(emon.Port.Cells olines, emon.Port.Cells owords, emon.Port.Cells text, int x, int y, int numeric) {
        // One OCR line of one word at (x, y), 40 wide and 20 high: `6.50` when `numeric` is 1, `abc` else.
        int tstart = emon.Port.CellsLen(text);
        int w = Evidence.OwCount(owords);
        if (numeric == 1) {
            emon.Port.CellsPush(text, 54);
            emon.Port.CellsPush(text, 46);
            emon.Port.CellsPush(text, 53);
            emon.Port.CellsPush(text, 48);
        } else {
            emon.Port.CellsPush(text, 97);
            emon.Port.CellsPush(text, 98);
            emon.Port.CellsPush(text, 99);
        }
        Evidence.OwNew(owords, 1, x, y, x + 40, y + 20, x, y, x + 40, y + 20, 0, 0, tstart, emon.Port.CellsLen(text) - tstart, Evidence.OlCount(olines), 800, 0);
        Evidence.OlNew(olines, 1, x, y, x + 40, y + 20, x, y, x + 40, y + 20, 0, 0, w, 1);
        return 0;
    }
    internal static int FtRows(emon.Port.Cells olines, emon.Port.Cells owords, emon.Port.Cells text, int rows, int cols, int numericCols, int jitter) {
        // `rows` rows of `cols` lines, the first `numeric-cols` numeric; the lines of a row are `jitter` points out of true by turns.
        int r = 0;
        int c = 0;
        int num = 0;
        while (r < rows) {
            c = 0;
            while (c < cols) {
                num = 0;
                if (c < numericCols) {
                    num = 1;
                }
                FtLine(olines, owords, text, 50 + (c * 100), (100 + (r * 40)) + (jitter * ((2 * (c - (2 * (c / 2)))) - 1)), num);
                c += 1;
            }
            r += 1;
        }
        return 0;
    }
    internal static int FormOf(int rows, int cols, int numericCols, int jitter, int receipt) {
        emon.Port.Cells olines = emon.Port.NewCells();
        emon.Port.Cells owords = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells scr = emon.Port.NewCells();
        FtRows(olines, owords, text, rows, cols, numericCols, jitter);
        return Ofall.FbForm(olines, owords, text, 0, rows * cols, receipt, scr);
    }
