        int at2 = FbWords(ans, 272, 30, 20013, 0, 0, 0);
        emon.Testport.AssertEq(Ofall.FbTessReads(ans, at2, scr), 0, "a Chinese page, which Tesseract without a language scores a fifth of Vision's characters on: Vision's");
        emon.Port.CellsDrop(ans, 0);
        int at3 = FbWords(ans, 272, 30, 1076, 0, 0, 0);
        emon.Testport.AssertEq(Ofall.FbTessReads(ans, at3, scr), 0, "a Cyrillic page");
        emon.Port.CellsDrop(ans, 0);
        int at4 = FbWords(ans, 272, 1, 97, 0, 0, 0);
        emon.Testport.AssertEq(Ofall.FbTessReads(ans, at4, scr), 1, "a reading too short to have a script: Tesseract may read it");
        emon.Port.CellsDrop(ans, 0);
        Plan.AnFail(ans, Plan.PkOcr(), 272, Plan.PsUnsupported());
        emon.Testport.AssertEq(Ofall.FbTessReads(ans, 0, scr), 0, "a page Vision refused is not this rule's");
    }
    [Xunit.Fact]
    public static void TestOnlyTheCandidatesTheTracerIsSureOfAreASeal() {
        emon.Port.Cells cand = emon.Port.NewCells();
        emon.Testport.AssertEq(Ofall.FbSealConf(), 700, "a candidate's primitive confidence of at least 700 per mille");
        emon.Testport.AssertEq(Ofall.FbSealHits(cand), 0, "no candidate: no seal");
        int k = 0;
        while (k < 16) {
            emon.Port.CellsPush(cand, 0);
            k += 1;
        }
        emon.Port.CellsSet(cand, 15, 300);
        emon.Testport.AssertEq(Ofall.FbSealHits(cand), 0, "a weak curve of a photographed receipt (300): not a seal");
        emon.Port.CellsSet(cand, 15, 928);
        emon.Testport.AssertEq(Ofall.FbSealHits(cand), 1, "a ring of 928: a seal");
        int k2 = 0;
        while (k2 < 16) {
            emon.Port.CellsPush(cand, 0);
            k2 += 1;
        }
        emon.Port.CellsSet(cand, 31, 856);
        emon.Testport.AssertEq(Ofall.FbSealHits(cand), 2, "and a stamp outline of 856: two");
    }
